/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeWHSInventFixedLocationWMSLocationId extends UPSPricingAttributeWHSInventFixedLocation implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSInventFixedLocation, WMSLocationId);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::String);
    WHSInventFixedLocation wHSInventFixedLocation;

    while select wHSInventFixedLocation
        group by WMSLocationId
    {
        if (! ret.in(wHSInventFixedLocation.WMSLocationId))
        {
            ret.add(wHSInventFixedLocation.WMSLocationId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventFixedLocation, WMSLocationId));
    qbr.value(queryValue(_value));
}
